node - <<'NODE'
const { chromium, devices } = require('playwright');
(async() => {
  const browser = await chromium.launch();

  const homeContext = await browser.newContext({ ...devices['iPhone 13'] });
  await homeContext.addInitScript(() => {
    window.localStorage.setItem('reader-active-shelf', 'gothic-fiction');
  });
  const homePage = await homeContext.newPage();
  const homeConsole = [];
  homePage.on('console', (msg) => homeConsole.push(msg.text()));
  await homePage.goto('http://localhost:3000/?shelf=category-romance', { waitUntil: 'networkidle' });
  const homeState = await homePage.evaluate(() => ({
    label: document.querySelector('[data-testid="active-shelf-label"]')?.textContent?.trim(),
    summary: document.querySelector('[data-testid="shelf-summary"]')?.textContent?.trim(),
    shortlistHooks: !!document.querySelector('[data-testid="shortlist-count"]'),
    firstCard: document.querySelector('[data-testid^="book-card-"] h3')?.textContent?.trim(),
    url: window.location.pathname + window.location.search,
  }));

  const compareContext = await browser.newContext();
  const comparePage = await compareContext.newPage();
  const requests = [];
  comparePage.on('requestfinished', async (request) => {
    requests.push(request.url());
  });
  await comparePage.goto('http://localhost:3000/compare', { waitUntil: 'networkidle' });
  const initialJs = requests.filter((url) => url.includes('/_next/static/') && url.endsWith('.js'));
  const initialRequestCount = initialJs.length;
  await comparePage.getByTestId('tab-advanced').click();
  await comparePage.getByTestId('advanced-content').waitFor({ state: 'visible' });
  await comparePage.waitForTimeout(500);
  const allJs = requests.filter((url) => url.includes('/_next/static/') && url.endsWith('.js'));
  const lateJs = allJs.slice(initialRequestCount);

  const leakContext = await browser.newContext();
  const leakPage = await leakContext.newPage();
  await leakPage.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
  for (let i = 0; i < 20; i += 1) {
    await leakPage.getByTestId(i % 2 === 0 ? 'shelf-tab-category-romance' : 'shelf-tab-gothic-fiction').click();
    await leakPage.getByTestId('shelf-search').fill(`probe ${i}`);
  }
  const probeResult = await leakPage.evaluate(() => {
    window.__shelfProbeRuns = 0;
    window.dispatchEvent(new Event('bookshelf:probe'));
    return window.__shelfProbeRuns;
  });

  console.log(JSON.stringify({
    home: {
      console: homeConsole,
      state: homeState,
    },
    compare: {
      initialJs,
      lateJs,
      advancedVisible: await comparePage.getByTestId('advanced-content').isVisible(),
    },
    probeRunsAfterOneEvent: probeResult,
  }, null, 2));

  await browser.close();
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
